preConditionHook:
// At least minSpikes separate same-direction SPIKES inside the last windowBars.
// Brooks: every spike, one bar or many, is a climax, and three of them is a
// wedge rather than a double top. A spike is the corpus's settled primitive --
// StrongTrendBarRun's test, a run of at least spikeBars consecutive with-trend
// bars whose body is at least bodyFraction of the bar's own range -- and two
// runs count separately only when a NON-spike bar lies between them.
//
// NOT ConsecutiveClimaxBarCount: that counts separated CLIMAX bars, each of
// which must be climaxMultiple x ATR tall, so it is a SIZE test at single bars.
// This counts RUNS of ordinary strong trend bars and never reads ATR, so the
// two fire on different bars. NOT MomentumConsecutiveBars either, which counts
// closes above the close N bars ago and has no body test.
//
// THE SCAN RUNS OLDEST TO NEWEST so the run counter is causal within the
// window. EasyLanguage's For only counts UP, so the loop index kk ascends and
// the BAR OFFSET bb = windowBars - 1 - kk descends -- bb is the bars-ago index,
// windowBars - 1 (oldest) first, 0 (this bar) last. The C++ is written the same
// way rather than with a descending loop, so the twins are statement for
// statement.
//
// COUNTING WITHOUT AN EQUALITY TEST: a maximal run is counted once, on the bar
// where its length first reaches spikeBars, and the countedUp latch keeps the
// rest of the same run from counting again. Written with el_ge and a latch
// rather than runUp == spikeBars because spikeBars is a double input and float
// equality is the corpus's standing trap. The latch clears on the same bar the
// run breaks, which is exactly the "separated by a non-spike bar" clause.
//
// Both directions are computed in the one loop. Every scratch value is a
// localVariables entry, never a hook-scope declaration, so the hooks can be
// emitted twice into one class; the counters and latches persist across bars
// and are all reset at the top.
//
// Deepest bar touched: windowBars - 1.
spikesUp = 0;
spikesDn = 0;
runUp = 0;
runDn = 0;
countedUp = false;
countedDn = false;
for (kk = 0; kk < (int)windowBars; ++kk) {
    bb = (int)windowBars - 1 - kk;
    isUp = el_gt(close[bb], open[bb]) && el_ge(close[bb] - open[bb], bodyFraction * (high[bb] - low[bb]));
    isDn = el_lt(close[bb], open[bb]) && el_ge(open[bb] - close[bb], bodyFraction * (high[bb] - low[bb]));
    if (isUp) {
        runUp = runUp + 1;
    } else {
        runUp = 0;
        countedUp = false;
    }
    if (isDn) {
        runDn = runDn + 1;
    } else {
        runDn = 0;
        countedDn = false;
    }
    if (el_ge((double)runUp, spikeBars) && countedUp == false) {
        spikesUp = spikesUp + 1;
        countedUp = true;
    }
    if (el_ge((double)runDn, spikeBars) && countedDn == false) {
        spikesDn = spikesDn + 1;
        countedDn = true;
    }
}
